// ============================================================
// ZONNEPLAN - BATTERIJHANDEL PRIJSINTERVALLEN
// ============================================================
// 00:00 -> 24:00
// 100 x 15 minuten
//
// prijsZP = prijs inclusief belasting / all-in
//
// state:
//   normal = grijs
//   charge = groen
//   sell   = oranje
//
// isNow:
//   true = huidig kwartier
// ============================================================


// ------------------------------------------------------------
// Zonneplan data
// ------------------------------------------------------------

var zonneplanObject =
    global.get("Zonneplan_morgen") || {};

var invoerData =
    Array.isArray(zonneplanObject.data)
        ? zonneplanObject.data
        : [];


// ------------------------------------------------------------
// Cheap / expensive gegevens
// ------------------------------------------------------------

var cheapSlots =
    global.get("ZonneplanCheapSlotMorgen") || [];

var expensiveSlots =
    global.get("ZonneplanExpensiveSlotMorgen") || [];


// ------------------------------------------------------------
// Gemiddelde goedkope prijs
// ------------------------------------------------------------

var cheapAvg =
    Number(
        global.get("ZonneplanCheapAvgMorgen")
    );


// ------------------------------------------------------------
// Duurste prijs
// ------------------------------------------------------------

var expensivePrice =
    Number(
        global.get("ZonneplanDuurstePrijsMorgen")
    );


// ============================================================
// HH:MM -> minuten
// ============================================================

function timeToMinutes(time) {

    if (!time) {
        return null;
    }

    var parts =
        String(time).trim().split(":");

    if (parts.length !== 2) {
        return null;
    }

    var hour =
        Number(parts[0]);

    var minute =
        Number(parts[1]);

    if (
        isNaN(hour) ||
        isNaN(minute)
    ) {
        return null;
    }

    if (
        hour < 0 ||
        hour > 23 ||
        minute < 0 ||
        minute > 59
    ) {
        return null;
    }

    return (
        hour * 60 +
        minute
    );
}


// ============================================================
// minuten -> HH:MM
// ============================================================

function minutesToTime(minutes) {

    minutes =
        (
            minutes + 1440
        ) % 1440;

    var hour =
        Math.floor(
            minutes / 60
        );

    var minute =
        minutes % 60;

    return (
        String(hour).padStart(2, "0") +
        ":" +
        String(minute).padStart(2, "0")
    );
}


// ============================================================
// INTERVALLEN UITVOUWEN
//
// Bijvoorbeeld:
//
// "12:00 - 15:45, 16:00 - 16:15"
//
// wordt:
//
// 12:00
// 12:15
// 12:30
// ...
// 15:30
// 16:00
//
// Eindtijd is exclusief.
// ============================================================

function expandSlotTexts(slotArray) {

    var result =
        new Set();


    if (
        slotArray === null ||
        slotArray === undefined
    ) {
        return result;
    }


    if (
        !Array.isArray(slotArray)
    ) {
        slotArray = [
            slotArray
        ];
    }


    for (
        var i = 0;
        i < slotArray.length;
        i++
    ) {

        var text =
            String(
                slotArray[i] || ""
            );


        // ----------------------------------------------------
        // Intervallen zoeken
        // ----------------------------------------------------

        var rangeRegex =
            /(\d{1,2}:\d{2})\s*-\s*(\d{1,2}:\d{2})/g;

        var match;

        var foundRange =
            false;


        while (
            (
                match =
                    rangeRegex.exec(text)
            ) !== null
        ) {

            foundRange =
                true;


            var start =
                timeToMinutes(
                    match[1]
                );

            var end =
                timeToMinutes(
                    match[2]
                );


            if (
                start === null ||
                end === null
            ) {
                continue;
            }


            // ------------------------------------------------
            // Normaal interval
            // ------------------------------------------------

            if (
                end > start
            ) {

                for (
                    var t = start;
                    t < end;
                    t += 15
                ) {

                    result.add(
                        minutesToTime(t)
                    );

                }

            }


            // ------------------------------------------------
            // Over middernacht
            // ------------------------------------------------

            else if (
                end < start
            ) {

                for (
                    var t1 = start;
                    t1 < 1440;
                    t1 += 15
                ) {

                    result.add(
                        minutesToTime(t1)
                    );

                }


                for (
                    var t2 = 0;
                    t2 < end;
                    t2 += 15
                ) {

                    result.add(
                        minutesToTime(t2)
                    );

                }

            }

        }


        // ----------------------------------------------------
        // Als er geen interval was:
        // losse tijden zoeken
        // ----------------------------------------------------

        if (
            !foundRange
        ) {

            var singleRegex =
                /\b(\d{1,2}:\d{2})\b/g;

            var singleMatch;


            while (
                (
                    singleMatch =
                        singleRegex.exec(text)
                ) !== null
            ) {

                var singleMinutes =
                    timeToMinutes(
                        singleMatch[1]
                    );


                if (
                    singleMinutes !== null
                ) {

                    result.add(
                        minutesToTime(
                            singleMinutes
                        )
                    );

                }

            }

        }

    }


    return result;
}


// ============================================================
// Cheap / expensive sets maken
// ============================================================

var cheapTimes =
    expandSlotTexts(
        cheapSlots
    );

var expensiveTimes =
    expandSlotTexts(
        expensiveSlots
    );


// ============================================================
// HUIDIGE TIJD
// ============================================================

var now =
    new Date();


// ------------------------------------------------------------
// Huidig kwartier
// ------------------------------------------------------------

var current =
    new Date(now);

current.setSeconds(
    0,
    0
);

current.setMinutes(
    Math.floor(
        current.getMinutes() / 15
    ) * 15
);


// ============================================================
// BEGIN VAN MORGEN
// ============================================================

var startOfDay = new Date(now);

startOfDay.setHours(0, 0, 0, 0);

// Eén dag vooruit
startOfDay.setDate(
    startOfDay.getDate() + 1
);


// ============================================================
// EINDE VAN MORGEN
// ============================================================

var endOfDay = new Date(startOfDay);

endOfDay.setDate(
    endOfDay.getDate() + 1
);


// ============================================================
// TIMESTAMPS
// ============================================================

var startTimestamp =
    startOfDay.getTime();

var endTimestamp =
    endOfDay.getTime();

var currentTimestamp = null;


// ============================================================
// ALLE PRIJZEN VOOR VANDAAG
// ============================================================

var allPrices = [];


for (
    var i = 0;
    i < invoerData.length;
    i++
) {

    var item =
        invoerData[i];


    if (
        !item ||
        !item.datum
    ) {
        continue;
    }


    // --------------------------------------------------------
    // Datum
    // --------------------------------------------------------

    var datum =
        new Date(
            item.datum
        );


    if (
        isNaN(
            datum.getTime()
        )
    ) {
        continue;
    }


    // --------------------------------------------------------
    // ALL-IN PRIJS
    // --------------------------------------------------------

    var prijsZP =
        Number(
            item.prijsZP
        );


    if (
        isNaN(prijsZP)
    ) {
        continue;
    }


    // --------------------------------------------------------
    // Rond tijdstip af op kwartier
    // --------------------------------------------------------

    datum.setSeconds(
        0,
        0
    );

    datum.setMinutes(
        Math.floor(
            datum.getMinutes() / 15
        ) * 15
    );


    var timestamp =
        datum.getTime();


    // --------------------------------------------------------
    // Alleen vandaag
    // --------------------------------------------------------

    if (
        timestamp <
        startTimestamp
    ) {
        continue;
    }

    if (
        timestamp >=
        endTimestamp
    ) {
        continue;
    }


    // --------------------------------------------------------
    // EURO -> CT/KWH
    //
    // 0.357822 euro
    // =
    // 35.7822 ct/kWh
    //
    // Mocht prijsZP al ct zijn, dan blijft het gelijk.
    // --------------------------------------------------------

    var prijsCt =
        prijsZP;


    if (
        Math.abs(
            prijsCt
        ) < 1
    ) {

        prijsCt *= 100;

    }


    // --------------------------------------------------------
    // Tijdtekst
    // --------------------------------------------------------

    var tijd =
        datum.toLocaleTimeString(
            "nl-NL",
            {
                hour: "2-digit",
                minute: "2-digit"
            }
        );


    allPrices.push({

        timestamp:
            timestamp,

        time:
            tijd,

        price:
            prijsCt

    });

}


// ============================================================
// SORTEREN
// ============================================================

allPrices.sort(
    function(a, b) {

        return (
            a.timestamp -
            b.timestamp
        );

    }
);


// ============================================================
// DUBBELE KWARTIEREN VERWIJDEREN
// ============================================================

var uniquePrices =
    [];

var seen =
    new Set();


for (
    var j = 0;
    j < allPrices.length;
    j++
) {

    var point =
        allPrices[j];


    if (
        seen.has(
            point.timestamp
        )
    ) {
        continue;
    }


    seen.add(
        point.timestamp
    );


    uniquePrices.push(
        point
    );

}


// ============================================================
// STATUS BEPALEN
// ============================================================

for (
    var k = 0;
    k < uniquePrices.length;
    k++
) {

    var p =
        uniquePrices[k];


    // standaard grijs
    p.state =
        "normal";


    // Cheap -> groen
    if (
        cheapTimes.has(
            p.time
        )
    ) {

        p.state =
            "charge";

    }


    // Expensive -> oranje
    //
    // Expensive krijgt voorrang.
    if (
        expensiveTimes.has(
            p.time
        )
    ) {

        p.state =
            "sell";

    }


    // Huidig kwartier
    p.isNow =
        (
            p.timestamp ===
            currentTimestamp
        );

}


// ============================================================
// MIN / MAX
// ============================================================

var values =
    uniquePrices
        .map(
            function(item) {
                return item.price;
            }
        )
        .filter(
            function(value) {
                return !isNaN(value);
            }
        );


var minPrice =
    values.length
        ? Math.min.apply(
            null,
            values
        )
        : 0;


var maxPrice =
    values.length
        ? Math.max.apply(
            null,
            values
        )
        : 30;


// ============================================================
// MAX VOOR GRAFIEK AFRONDEN
// ============================================================

maxPrice =
    Math.ceil(
        maxPrice / 5
    ) * 5;


if (
    maxPrice < 10
) {

    maxPrice =
        10;

}


// ============================================================
// HUIDIGE PRIJS
// ============================================================

var currentPoint =
    uniquePrices.find(
        function(item) {

            return (
                item.isNow === true
            );

        }
    );


// ============================================================
// CHARGE AVG
// ============================================================

var chargePrice =
    null;


if (
    !isNaN(
        cheapAvg
    )
) {

    chargePrice =
        Math.abs(
            cheapAvg
        ) < 1
            ? cheapAvg * 100
            : cheapAvg;

}


// ============================================================
// SELL PRICE
// ============================================================

var sellPrice =
    null;


if (
    !isNaN(
        expensivePrice
    )
) {

    sellPrice =
        Math.abs(
            expensivePrice
        ) < 1
            ? expensivePrice * 100
            : expensivePrice;

}


// ============================================================
// OUTPUT
// ============================================================

msg.payload = {

    prices:
        uniquePrices,

    now:
        currentTimestamp,

    currentPrice:
        currentPoint
            ? currentPoint.price
            : null,

    chargePrice:
        chargePrice,

    sellPrice:
        sellPrice,

    minPrice:
        minPrice,

    maxPrice:
        maxPrice,

    count:
        uniquePrices.length,

    cheapCount:
        cheapTimes.size,

    expensiveCount:
        expensiveTimes.size

};


// ============================================================
// STATUS
// ============================================================

node.status({

    fill: "green",

    shape: "dot",

    text:
        uniquePrices.length +
        " kwartieren | " +
        cheapTimes.size +
        " cheap | " +
        expensiveTimes.size +
        " expensive"

});


return msg;
